// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address user = address(this);
        uint deposit = 42;
        vm.deal(user, deposit);
        vm.prank(user);
        c.addToBalance{value: deposit}();
        uint got = c.getBalance(user);
        assertTrue(got == deposit, "getBalance should return deposited amount");
    }
}
